// Emal neticesini insanin oxuyacagi hesabata cevirir.
//
// Niye Code node? Sertler var: sebet bos ola biler, qalib market olmaya biler.
// Sertli metn ucun kod sablondan aydindir.

const extract = $('AI ile mehsullari cixar').first().json;
const compare = $input.first().json;

const lines = [];
lines.push('BasketIQ - ' + new Date().toISOString().slice(0, 10));
lines.push('');
lines.push('Kataloq #' + extract.catalog_id + ' (' + extract.store + ')');
lines.push('  ' + extract.processed + ' setir emal olundu, ' + extract.saved + ' mehsul yazildi.');

const yeni = (extract.products || []).slice(0, 5)
  .map(function (p) { return '  - ' + p.name + ': ' + p.price + ' AZN'; });
if (yeni.length) {
  lines.push('');
  lines.push('Yeni qiymetler:');
  lines.push.apply(lines, yeni);
}

lines.push('');
if (compare.best) {
  lines.push('Sebet en ucuz: ' + compare.best.store + ' - ' + compare.best.total + ' AZN');
  if (compare.savings) {
    lines.push('Qenaet: ' + compare.savings + ' AZN');
  }
} else {
  lines.push(compare.note || 'Sebet bosdur - muqayise edilmedi.');
}

return [{ json: { hesabat: lines.join('\n'), kataloq_id: extract.catalog_id } }];

// Yeni kataloq yoxdur - normal haldir, xeta deyil.

const data = $input.first().json;
const otürülen = (data.skipped || []).length;
return [{ json: {
  hesabat: 'BasketIQ: yeni kataloq yoxdur (' + otürülen + ' otürüldü).',
  kataloq_id: null,
} }];

// Yoxlamanin neticesini insanin oxuyacagi bir setre cevirir.
//
// «changed» sahesi endpoint-den gelir: profildeki gozlenilen veziyyetle
// real veziyyet fərqlidirse true olur. Yeni «her gun eyni cavab» ile
// «BU GUN FERQLIDIR» arasindaki ferq mehz odur - hesabatda da yalniz
// bu ferq vurgulanir, eks halda gundelik setir sesə cevrilir.
const r = $input.first().json;
const ad = r.slug;
let setir;
if (r.changed && r.alive) {
  setir = `DIQQET: ${ad} saytı QAYITDI (${r.note}). `
        + `profiles.py-de status yenilenmelidir.`;
} else if (r.changed) {
  setir = `DIQQET: ${ad} isleyirdi, indi cavab vermir (${r.note}).`;
} else {
  setir = `${ad}: deyisiklik yoxdur (${r.note}).`;
}
return [{ json: { menbe_hesabati: setir, slug: ad, alive: r.alive, changed: r.changed } }];
